insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 9, 'Então, quê? Somos nós melhores? Não, de maneira nenhuma. Pois já delatamos que todos, tanto judeus como gregos, estão debaixo do pecado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 10, 'como está escrito: Não há justo, nem um sequer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 11, 'Ninguém há que entenda, ninguém há que busque a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 12, 'Todos se desviaram, e juntamente se tornaram inúteis. “Não há quem faça o bem, não há um sequer”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 13, '“Suas gargantas são sepulcro aberto; com suas línguas enganam”; “veneno de serpentes está sob seus lábios”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 14, '“Suas bocas estão cheias de maldição e amargura”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 15, '“Seus pés são velozes para derramar sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 16, 'Destruição e miséria há em seus caminhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 17, 'e não conheceram o caminho da paz”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 18, '“Diante dos seus olhos não há temor a Deus”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 19, 'Ora, sabemos que tudo o que a Lei diz, diz aos que estão na Lei, para que toda boca se cale, e todo o mundo seja condenável perante Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 20, 'Assim, ninguém será justificado diante dele pelas obras da Lei, porque o que vem pela Lei é o conhecimento do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 21, 'Mas agora, independentemente da Lei, a justiça de Deus se manifestou, tendo testemunho da Lei e dos Profetas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 22, 'isto é, a justiça de Deus por meio da fé em Jesus Cristo, para todos e sobre todos os que creem; pois não há diferença;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 23, 'porque todos pecaram, e estão destituídos da glória de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 24, 'e são justificados gratuitamente pela sua graça, por meio da redenção que há em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 25, 'Deus propôs Jesus por sacrifício de reconciliação, pela fé em seu sangue, para demonstrar a sua justiça. Ele deixou de considerar os pecados antes cometidos, sob a paciência de Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 26, 'para demonstrar a sua justiça neste presente tempo, a fim de que ele seja justo, e justificador daquele que tem fé em Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 27, 'Onde, pois, está o orgulho? Este é excluído. Por qual lei? A das obras? Não, mas sim, pela Lei da fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 28, 'Concluímos, portanto, que o ser humano é justificado pela fé, independentemente das obras da Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 29, 'Por acaso Deus é somente dos judeus, e não também dos gentios? Certamente que dos gentios também;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 30, 'já que há um só Deus, que justificará pela fé os circuncisos, e por meio da fé os incircuncisos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 3, 31, 'Por acaso anulamos a Lei pela fé? De maneira nenhuma. Pelo contrário, confirmamos a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 1, 'Então, que diremos que Abraão, nosso ancestral segundo a carne, obteve?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 2, 'Pois se Abraão foi justificado pelas obras, ele tem do que se orgulhar, mas não diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 3, 'Pois o que diz a Escritura? Abraão creu em Deus, e isso lhe foi lhe imputado como justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 4, 'Ora, ao que trabalha, seu pagamento não é considerado um favor, mas sim, uma dívida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 5, 'Porém, ao que não tem obra, mas crê naquele que torna justo o ímpio, sua fé lhe é reputada como justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 6, 'Desta maneira, também Davi afirma que bendito é aquele a quem Deus atribui justiça independentemente das obras:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 7, 'Benditos são os que têm as transgressões perdoadas, e seus pecados são cobertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 8, 'Bendito é o homem a quem o Senhor não atribui pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 9, 'Ora, essa bendição [é somente] para os circuncisos, ou também para os incircuncisos? Pois dizemos que a fé a Abraão foi reputada como justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 10, 'Como, pois, [lhe] foi reputada? Enquanto ele estava na circuncisão ou na incircuncisão? Não na circuncisão, mas sim, na incircuncisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 11, 'E ele recebeu o sinal da circuncisão como selo da justiça da fé quando ainda era incircunciso, para que fosse pai de todos os que creem, ainda que não estejam circuncidados, para que a justiça também lhes seja imputada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 12, 'e para que fosse pai da circuncisão, dos que não somente são circuncidados, mas que também andam nos passos da fé do nosso pai Abraão, quando ainda não era circuncidado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 13, 'Pois não foi pela Lei que a promessa de ser herdeiro do mundo [foi feita] a Abraão ou à sua descendência, mas sim, pela justiça da fé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 14, 'porque, se é da Lei que são os herdeiros, logo a fé se torna vazia, e a promessa é anulada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 15, 'Pois a Lei produz ira, porque onde não há Lei, também não há transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 16, 'Por isso é pela fé, para que seja conforme a graça, a fim de que a promessa seja confirmada a todos os descendentes, não somente aos que são da Lei, mas também aos que são da fé de Abraão, que é Pai de todos nós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 17, '(como está escrito: “Eu te constituí pai de muitas nações”) diante daquele em quem ele creu, Deus, que vivifica os mortos, e chama as coisas que não são como se já fossem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 18, 'Com esperança, [Abraão] creu, contra as expectativas, que se tornaria pai de muitas nações, conforme o que [lhe] fora dito: “Assim será a tua descendência”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 19, 'Ele não fraquejou na fé, não dando atenção ao seu próprio corpo já praticamente morto (pois já era de quase cem anos), nem ao estado de morte do ventre de Sara;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 20, 'nem duvidou da promessa de Deus; pelo contrário, fortaleceu-se na fé, dando glória a Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 21, 'e teve plena certeza de que aquele que havia prometido também era poderoso para cumprir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 22, 'Por esse motivo que também isso lhe foi imputado como justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 23, 'Ora, não só por causa dele está escrito que lhe foi imputado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 24, 'mas também por nós, a quem será imputado, aos que creem naquele que ressuscitou dos mortos a Jesus, nosso Senhor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 4, 25, 'que foi entregue por nossos pecados, e ressuscitou para a nossa justificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 1, 'Portanto, agora que somos justificados pela fé, temos paz com Deus por meio do nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 2, 'Por meio dele também temos acesso pela fé a esta graça, na qual estamos firmes, e nos alegramos na esperança da glória de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 3, 'E não somente [isso] , mas também nos alegramos nas tribulações, sabendo que a tribulação produz paciência;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 4, 'a paciência [produz] experiência, e a experiência [produz] esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 5, 'E a esperança não frustra, porque o amor de Deus está derramado em nossos corações pelo Espírito Santo que nos foi dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 6, 'Pois quando ainda éramos fracos, Cristo morreu a seu tempo pelos ímpios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 7, 'Ora, dificilmente alguém morre por um justo, ainda que talvez alguém possa ousar morrer por uma boa pessoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 8, 'Mas Deus prova o seu amor por nós através de Cristo haver morrido por nós, quando ainda éramos pecadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 9, 'Por isso, muito mais agora, que já somos justificados por seu sangue, seremos por ele salvos da ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 10, 'Pois, se quando éramos inimigos, fomos reconciliados com Deus pela morte do seu Filho, muito mais, tendo sido reconciliados, seremos salvos pela sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 11, 'E não somente [isso] , mas também nos alegramos em Deus por meio do nosso Senhor Jesus Cristo, por quem agora recebemos a reconciliação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 12, 'Portanto, assim como por um homem o pecado entrou no mundo, e pelo pecado a morte, assim também a morte passou a todos os seres humanos, porque todos pecaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 13, 'Pois, antes da Lei, o pecado [já] existia no mundo; porém, quando não há Lei, o pecado não é considerado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 14, 'Mas a morte reinou desde Adão até Moisés, até sobre aqueles que não pecaram à semelhança da transgressão de Adão, o qual era uma figura daquele que estava para vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 15, 'Mas o dom gratuito não é como a transgressão; porque, se pela transgressão de um, muitos morreram, muito mais a graça de Deus, e o dom pela graça de um homem, Jesus Cristo, têm sido abundantes sobre muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 16, 'E o dom não é como [a transgressão] de um que pecou; porque o julgamento de uma só [transgressão] trouxe condenação, mas o dom gratuito, de muitas transgressões, trouxe justificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 17, 'Pois, se pela transgressão de um, a morte reinou por causa desse, muito mais os que recebem a abundância da graça, e do dom da justiça reinarão em vida por um só, Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 18, 'Portanto, assim como uma transgressão resultou em condenação sobre todos os seres humanos, assim também um ato de justiça resultou em justificação da vida sobre todos os seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 19, 'Pois, assim como pela desobediência de um só homem muitos foram feitos pecadores, assim também, pela obediência de um só, muitos serão justificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 20, 'A Lei veio para que a transgressão aumentasse; mas onde o pecado aumentou, a graça superabundou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 5, 21, 'a fim de que, assim como o pecado reinou para a morte, também a graça reine pela justiça para a vida eterna, por meio de Jesus Cristo, nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 1, 'Que diremos, pois? Continuaremos no pecado, para que a graça aumente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 2, 'De maneira nenhuma! Nós, que morremos para o pecado, como ainda viveremos nele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 3, 'Ou não sabeis que todos os que somos batizados em Cristo Jesus, somos batizados em sua morte?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 4, 'Por isso, estamos sepultados com ele pelo batismo na morte; para que, assim como Cristo ressuscitou dos mortos para a glória do Pai, assim também nós andemos em novidade de vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 5, 'Pois, se fomos unidos [a ele] na semelhança de sua morte, também o seremos na da [sua] ressurreição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 6, 'E sabemos isto: que o nosso velho ser foi crucificado com [ele] , para que o corpo do pecado seja extinto, a fim de que não mais sirvamos ao pecado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 7, 'pois o que está morto já está absolvido do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 8, 'Ora, se já morremos com Cristo, cremos que também com ele viveremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 9, 'Porque sabemos que, depois que Cristo foi ressuscitado dos mortos, já não morre mais; a morte já não mais o domina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 10, 'Pois, ao morrer, ele morreu para o pecado de uma vez por todas; mas, ao viver, vive para Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 11, 'Assim também vós, considerai que estais mortos para o pecado, mas vivendo para Deus, em Cristo Jesus, nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 12, 'Portanto, não reine o pecado em vosso corpo mortal, para obedecer a ele em seus maus desejos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 13, 'Nem apresenteis os membros do vosso corpo ao pecado como instrumentos de injustiça; em vez disso, apresentai-vos a Deus, como vivos dentre os mortos, e vossos membros como instrumentos de justiça para Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 14, 'Pois o pecado não vos dominará, porque não estais sob a Lei, mas sim, sob a graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 15, 'Então, quê? Pecaremos, já que não estamos sob a Lei, mas sob a graça? De maneira nenhuma!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 16, 'Não sabeis vós, que a quem vos apresentardes por servos para obedecer, sois servos daquele a quem obedeceis? Ou do pecado para a morte, ou da obediência para a justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 17, 'Porém, graças a Deus que vós éreis servos do pecado, mas [agora] , de coração obedeceis à forma de doutrina a que vós fostes entregues;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 18, 'e, sendo libertos do pecado, vos tornastes servos da justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 19, 'Estou falando na lógica humana, pela fraqueza de vossa carne. Pois, assim como apresentastes os membros do vosso corpo como servos da impureza e da maldade para a maldade, assim também apresentai agora os vossos membros como servos da justiça para a santificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 20, 'Porque quando éreis servos do pecado, estáveis livres da justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 21, 'Afinal, que fruto obtivestes das coisas de que agora vos envergonhais? Pois o fim delas é a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 22, 'Mas agora, libertos do pecado, e feitos servos de Deus, tendes o vosso fruto para a santificação, e por fim a vida eterna;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 6, 23, 'porque o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 1, 'Não sabeis vós, irmãos (pois estou falando com os que entendem a Lei), que a Lei domina o ser humano por todo o tempo que vive?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 2, 'Pois a mulher casada está, pela Lei, ligada ao marido enquanto o ele viver; porém, depois do marido morrer, ela está livre da Lei do marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 3, 'Ou seja, enquanto o marido viver, ela será chamada de adúltera, se for de outro homem; mas depois de morto o marido, ela está livre da Lei, de maneira que não será adúltera se for de outro homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 4, 'Assim, meus irmãos, também vós estais mortos para a Lei por meio do corpo de Cristo, para que sejais de outro, daquele que foi ressuscitado dos mortos, a fim de frutificarmos para Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 5, 'Pois, quando estávamos na carne, as paixões dos pecados, que eram pela Lei, operavam nos membros do nosso corpo, a fim de frutificarem para a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 6, 'Mas agora estamos livres da Lei, estando mortos para aquilo em que estávamos presos, para que sirvamos em novidade de espírito, e não na velhice da norma escrita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 7, 'Que diremos, pois? É a Lei pecado? De maneira nenhuma! Todavia, eu não teria conhecido o pecado, se não fosse pela Lei; porque não conheceria a cobiça, se a Lei não dissesse: Não cobiçarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 8, 'Mas o pecado, aproveitando-se do mandamento, operou em mim toda variedade de cobiça. Pois sem a Lei o pecado [estaria] morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 9, 'Antes eu vivia sem a Lei; mas quando veio o mandamento, o pecado reviveu, e eu morri;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 10, 'e descobri que o mandamento, que era para a vida, resultou-me para a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 11, 'Pois o pecado, aproveitando o mandamento, me enganou, e por ele me matou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 12, 'Portanto, a Lei é santa, e o mandamento é santo, justo, e bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 13, 'Então o que é bom se tornou para mim morte? De maneira nenhuma! Mas foi o pecado, para que se mostrasse como pecado, que operou a morte em mim por meio do bem, a fim de que, por meio do mandamento, o pecado se tornasse excessivamente pecaminoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 14, 'Pois sabemos que a Lei é espiritual; mas eu sou carnal, vendido como servo do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 15, 'Porque não entendo o que faço, pois o que quero, isso não faço; mas o que eu odeio, isso faço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 16, 'E se faço o que não quero, consinto que a Lei é boa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 17, 'De maneira que agora não sou mais eu que faço aquilo, mas sim, o pecado que habita em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 18, 'Porque sei que em mim, isto é, em minha carne, não habita bem algum; porque o querer está em mim; porém o fazer o bem eu não consigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 19, 'Pois o bem que quero, não faço; mas o mal que não quero, isso faço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 20, 'Ora, se faço o que não quero, não sou eu que faço, mas sim, o pecado que habita em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 21, 'Acho, então, esta lei: que quando quero fazer o bem, o mal está comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 22, 'Pois, quanto ao ser interior, tenho prazer na Lei de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 23, 'mas em meus membros vejo outra lei, que batalha contra a lei do meu entendimento, e me prende sob a lei do pecado, que está nos meus membros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 24, 'Miserável homem [que sou] ! Quem me livrará deste corpo de morte?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 7, 25, 'Agradeço a Deus por Jesus Cristo, nosso Senhor. Assim, eu mesmo com o entendimento sirvo à Lei de Deus, mas, com a carne, à lei do pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 1, 'Portanto, agora, nenhuma condenação há para os que estão em Cristo Jesus, que não andam segundo a carne, mas sim segundo o Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 2, 'Porque a Lei do Espírito de vida, em Cristo Jesus, me livrou da lei do pecado e da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 3, 'Pois o que era impossível para a lei, porque estava enferma pela carne, Deus, ao enviar o seu próprio Filho em semelhança da carne pecadora, e por causa do pecado, condenou o pecado na carne,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 4, 'para que a exigência da lei se cumprisse em nós, que andamos, não segundo a carne, mas sim, segundo o Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 5, 'Pois os que são segundo a carne voltam sua mentalidade para as coisas da carne, mas os que são segundo o Espírito, para as coisas do Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 6, 'Pois a mentalidade da carne é morte, mas a mentalidade do Espírito é vida e paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 7, 'Pois a mentalidade da carne é inimizade contra Deus, pois não se sujeita à Lei de Deus, porque nem sequer pode.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 8, 'Portanto, os que permanecem na carne não podem agradar a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 9, 'Porém vós não permaneceis na carne, mas sim, no Espírito, se é que o Espírito de Deus habita em vós. Porém, se alguém não tem o Espírito de Cristo, esse não lhe pertence.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 10, 'E se Cristo está em vós, apesar do corpo estar morto por causa do pecado, o Espírito é vida por causa da justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 11, 'E se o Espírito daquele que dos mortos ressuscitou a Jesus habita em vós, aquele que dos mortos ressuscitou a Cristo também dará vida aos vossos corpos mortais por meio do seu Espírito, que habita em vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 12, 'Por isso, irmãos, somos devedores, não à carne, para vivermos segundo a carne;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 13, 'porque, se viverdes segundo a carne, morrereis; mas se, pelo Espírito, fizerdes morrer as ações do corpo, vivereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 14, 'Pois todos quantos são guiados pelo Espírito de Deus são filhos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 15, 'Pois não recebestes o espírito de escravidão, para voltardes ao medo; mas recebestes o Espírito de adoção como filhos, pelo qual clamamos: Aba, Pai!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 16, 'O próprio Espírito dá testemunho com o nosso espírito de que somos filhos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 17, 'E, se somos filhos, logo somos também herdeiros; herdeiros de Deus, e coerdeiros de Cristo; se sofremos com ele, é para que também com ele sejamos glorificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 18, 'Pois considero que as aflições deste tempo presente nem se comparam com a glória que nos será revelada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 19, 'Pois a criação espera ansiosamente a revelação dos filhos de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 20, 'porque a criação ficou sujeita à futilidade (não por vontade própria, mas sim por causa daquele que a sujeitou),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 21, 'na esperança de que também a mesma criação seja liberta da escravidão da degradação para a liberdade da glória dos filhos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 22, 'Pois sabemos que toda a criação geme e sofre dores como as de parto até agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 23, 'E não somente [isso] , mas também nós, que temos os primeiros frutos do Espírito, gememos em nós mesmos, esperando a [adoção] , [isto é] , a redenção do nosso corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 24, 'Pois fomos salvos na esperança. Ora, a esperança que se vê não é esperança; afinal, por que alguém ainda espera o que já vê?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 25, 'Mas, se esperamos o que não vemos, com paciência esperamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 26, 'E da mesma maneira também o Espírito ajuda em nossas fraquezas. Pois não sabemos orar como se deve, mas o próprio Espírito intercede por nós com gemidos inexprimíveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 27, 'E aquele que examina os corações sabe qual é a intenção do Espírito, pois ele intercede pelos santos, segundo [a vontade] de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 28, 'E sabemos que todas as coisas juntamente contribuem para o bem daqueles que amam a Deus, dos que são chamados segundo o seu propósito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 29, 'Pois aos que desde antes conheceu, também os predestinou para serem conformes à imagem do seu Filho, para que ele seja o primogênito entre muitos irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 30, 'E aos que predestinou, a esses também chamou; e aos que chamou, a esses também justificou; e aos que justificou, a esses também glorificou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 31, 'Então, que diremos acerca dessas coisas? Se Deus é por nós, quem será contra nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 32, 'Aquele que nem mesmo ao seu próprio Filho poupou, como não nos dará também com ele todas as coisas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 33, 'Quem fará acusação contra os escolhidos de Deus? Deus é quem justifica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 34, 'Quem [os] condenará? Cristo é o que morreu; além disto é o que também ressuscitou; o que também está à direita de Deus, e que intercede por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 35, 'Quem nos separará do amor de Cristo? A aflição, a angústia, a perseguição, a fome, a nudez, o perigo, ou a espada?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 36, 'Como está escrito: “Pois por causa de ti somos entreges à morte o dia todo; somos contados como ovelhas para o matadouro”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 37, 'Mas em todas estas coisas somos mais que vencedores, por meio daquele que nos amou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 38, 'Pois tenho certeza que nem a morte, nem a vida, nem anjos, nem principados, nem poderes, nem o presente, nem o futuro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 8, 39, 'nem altura, nem profundeza, nem qualquer outra criatura poderá nos separar do amor de Deus, que está em Cristo Jesus, nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 1, 'Digo a verdade em Cristo, não minto, e minha consciência dá testemunho comigo pelo Espírito Santo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 2, 'de que tenho grande tristeza e contínuo tormento em meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 3, 'Porque desejaria eu mesmo ser separado de Cristo em proveito dos meus irmãos, que são meus parentes segundo a carne;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 4, 'que são israelitas, e a quem pertencem a adoção como filhos, a glória, os pactos, a Lei, o culto, e as promessas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 5, 'deles são os patriarcas, e deles, quanto à carne, é Cristo, que é sobre todos, Deus bendito eternamente, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 6, 'Não que a palavra de Deus tenha falhado; porque nem todos os que são de Israel são [verdadeiros] israelitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 7, 'Nem por serem descendentes de Abraão são todos filhos, mas: “Em Isaque será chamada a tua descendência”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 8, 'Isto é, não são os filhos da carne que são os filhos de Deus; mas sim os filhos da promessa que são contados como descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 9, 'Pois esta é a palavra da promessa: Aproximadamente a este tempo virei, e Sara terá um filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 10, 'E não somente isso, mas também Rebeca, quando esteve grávida por intermédio de um só, Isaque, nosso ancestral'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 11, '(pois, como não eram ainda nascidos, não haviam feito bem ou mal, para que o propósito de Deus, segundo a escolha, continuasse; não pelas obras, mas por causa daquele que chama),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 12, 'foi dito a ela: O mais velho servirá o mais jovem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 13, 'como está escrito: “Amei Jacó, mas odiei Esaú”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 14, 'Que diremos, então? Que há injustiça da parte de Deus? De maneira nenhuma!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 15, 'Pois ele diz a Moisés: “Terei misericórdia de quem eu tiver misericórdia, e me compadecerei de quem eu me compadecer”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 16, 'Portanto, não [depende] daquele que quer, nem daquele que se esforça, mas sim, de Deus, que se compadece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 17, 'Pois a Escritura diz a Faraó: “Para isto mesmo te levantei: para mostrar em ti o meu poder, e para que o meu nome seja anunciado em toda a terra”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 18, 'Portanto, ele tem misericórdia de quem quer, e endurece a quem quer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 19, 'Tu, então, me dirás: “Por que ele ainda se queixa? Pois quem resiste à sua vontade?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 20, 'Mas antes, quem és tu, ó, humano, para questionares a Deus? Por acaso a coisa formada dirá ao que a formou: “Por que me fizeste assim?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 21, 'Ou não tem o oleiro poder sobre o barro, para da mesma massa fazer um vaso para honra, e outro para desonra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 22, 'E se Deus, querendo mostrar a [sua] ira, e dar a conhecer o seu poder, suportou com muita paciência os vasos da ira, preparados para a perdição,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 23, 'a fim de fazer conhecidas as riquezas da sua glória nos vasos da misericórdia, que preparou com antecedência para a glória,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 24, 'que somos nós, aos quais ele chamou, não somente dentre os judeus, mas também dentre os gentios?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 25, 'Como também diz em Oseias: “Ao que era Não-Meu-Povo, chamarei de Meu-Povo; e a que não era Não-Amada, [chamarei] de Amada”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 26, 'E será que, no lugar onde lhes foi dito: “Vós não sois meu povo, Aí serão chamados filhos do Deus vivo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 27, 'Também Isaías clama acerca de Israel: “Ainda que o número dos filhos de Israel seja como a areia do mar, [apenas] o remanescente será salvo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 28, 'porque o Senhor concluirá e executará brevemente a sentença em justiça; pois ele fará uma breve sentença sobre a terra”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 29, 'E como Isaías predisse: “Se o Senhor dos Exércitos não houvesse nos deixado descendência, nós nos teríamos tornado como Sodoma, e como Gomorra teríamos sido semelhantes”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 30, 'Então, que diremos? Que os gentios, que não buscavam a justiça, alcançaram a justiça, mas a justiça que é pela fé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 31, 'porém, Israel, que buscava a Lei da justiça, não alcançou a Lei da justiça'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 32, 'Por quê? Porque não [a buscavam] pela fé, mas sim, como que pelas obras da Lei;pois tropeçaram na pedra de tropeço,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 9, 33, 'como está escrito: “Eis que ponho em Sião uma pedra de tropeço, e uma rocha que causa queda; e todo aquele que nela crer não será envergonhado”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 1, 'Irmãos, o bom desejo do meu coração, e a oração que [faço] a Deus por Israel, é que sejam salvos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 2, 'Pois lhes dou testemunho de que eles têm zelo por Deus, mas não com entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 3, 'Pois, como ignoraram a justiça de Deus, e procuraram estabelecer a sua própria justiça, eles não se sujeitaram à justiça de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 4, 'Porque o fim da Lei é Cristo, para justiça de todo aquele que crê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 5, 'Pois Moisés descreve a justiça que é pela Lei: “A pessoa que praticar estas coisas viverá por elas”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 6, 'Mas a justiça que é pela fé assim diz: “Não digas em teu coração: ‘Quem subirá ao céu?’ (Isto é, trazer Cristo abaixo),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 7, 'ou: ‘Quem descerá ao abismo?’” (Isto é, trazer Cristo dentre os mortos).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 8, 'Porém, o que diz? “A palavra está perto de ti, na tua boca, e no teu coração”. Esta é a palavra da fé, que pregamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 9, 'Pois, se com a tua boca declarares que Jesus é Senhor, e em teu coração creres que Deus o ressuscitou dos mortos, serás salvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 10, 'Pois com o coração se crê para a justiça, e com a boca se confessa para a salvação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 11, 'Porque a Escritura diz: “Todo aquele que nele crê não será envergonhado.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 12, 'Pois não há diferença entre judeu e grego, porque um mesmo é o Senhor de todos, rico para todos os que o invocam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 13, 'Pois: “Todo aquele que invocar o nome do Senhor será salvo.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 14, 'Mas como invocarão aquele em quem não creram? E como crerão naquele de quem não ouviram? E como ouvirão, sem haver quem pregue?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 15, 'E como pregarão, se não forem enviados? Como está escrito: “Como são agradáveis os pés dos que anunciam o evangelho da paz, dos que anunciam as boas novas!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 16, 'Mas nem todos obedeceram ao evangelho, pois Isaías diz: “Senhor, quem creu na nossa pregação?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 17, 'Portanto, a fé [vem] pelo ouvir, e o ouvir pela palavra de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 18, 'Mas pergunto: por acaso não ouviram? Sim, certamente. [Pois:] “Sua voz saiu por toda a terra, e suas palavras até os confins do mundo.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 19, 'Mas pergunto: por acaso Israel não entendeu? Primeiramente Moisés disse: “Eu vos provocarei ciúmes com os que não são do povo; com uma nação insensata vos provocarei à ira.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 20, 'E Isaías ousou dizer: “Fui achado pelos que não me buscavam; fui revelado aos que por mim não perguntavam.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 10, 21, 'Mas sobre Israel diz: “Todo o dia estendi as minhas mãos a um povo rebelde e hostil.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 1, 'Então pergunto: por acaso Deus rejeitou seu povo? De maneira nenhuma! Pois também eu sou israelita, da descendência de Abraão, da tribo de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 2, 'Deus não rejeitou seu povo, o qual desde antes conhecia. Ou não sabeis o que a Escritura diz de Elias? Como ele fala a Deus, contra Israel, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 3, '“Senhor, mataram os teus profetas, e derrubaram os teus altares; só eu fiquei, e buscam tirar-me a vida.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 4, 'Mas o que lhe disse a divina resposta? “Reservei para mim sete mil homens que não dobraram os joelhos a Baal.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 5, 'Portanto, também agora no presente tempo ficou um remanescente, escolhido pela graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 6, 'E, se é pela graça, logo não é pelas obras; de outra maneira, a graça já não é graça. E se é pelas obras, logo não é [pela] graça; de outra maneira a obra já não é obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 7, 'Então, quê? O que Israel busca, isso não obteve; mas os escolhidos o obtiveram, e os demais foram endurecidos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 8, 'como está escrito: “Deus lhes deu espírito de insensibilidade; olhos que não veem, e ouvidos que não ouvem; até o dia de hoje.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 9, 'E Davi diz: “A mesa deles se torne em laço e armadilha; em meio de tropeço e retribuição para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 10, 'Seus olhos se escureçam, para que não vejam, e suas costas fiquem constantemente encurvadas.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 11, 'Então, pergunto: por acaso tropeçaram para que caíssem? De maneira nenhuma! Mas pela queda deles a salvação [veio] aos gentios, para lhes provocarem ciúmes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 12, 'Ora, se a queda deles é o enriquecimento do mundo, e se o prejuízo deles é o enriquecimento dos gentios, quanto mais a sua plenitude!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 13, 'Pois falo a vós mesmos, gentios; como sou apóstolo dos gentios, honro meu ministério,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 14, 'a fim de que, de alguma maneira, eu provoque ciúmes aos do meu povo, e salve alguns deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 15, 'Pois, se a rejeição deles é a reconciliação do mundo, o que será sua admissão, senão vida dentre os mortos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 16, 'E se as primícias são santas, a massa também é; e se a raiz é santa, os ramos também são.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 17, 'Porém, se alguns dos ramos foram quebrados e separados, e sendo tu oliveira selvagem, foste enxertado no lugar deles, e feito participante da raiz, e nutrido pela boa oliveira,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 18, 'não te orgulhes de ser melhor que os ramos. Mesmo se te orgulhares, não és tu que sustentas a raiz, mas sim, a raiz a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 19, 'Tu, então, dirás: “Os ramos foram quebrados para que eu fosse enxertado.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 20, 'É verdade. Por causa da incredulidade eles foram quebrados, e tu, por causa da fé estás firme. Não tenhas orgulho, mas sim temor,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 21, 'pois, se Deus não poupou os ramos naturais, ele poderá não poupar a ti também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 22, 'Olha, pois, a bondade e severidade de Deus; a severidade sobre os que caíram, mas a bondade sobre ti, se continuares na bondade; de outra maneira, também tu serás cortado fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 23, 'E também eles, se não continuarem na incredulidade, serão enxertados, porque Deus é poderoso para enxertá-los de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 24, 'Pois, se tu foste cortado da oliveira naturalmente selvagem, e contra a natureza enxertado na oliveira boa, quanto mais estes, que são naturais, serão enxertados na sua própria oliveira!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 25, 'Não quero, irmãos, que ignoreis este mistério, para que não sejais sábios apenas a vós mesmos: o endurecimento veio em parte sobre Israel, até que a plenitude dos gentios tenha entrado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 26, 'e assim, todo o Israel será salvo, como está escrito: “O Libertador virá de Sião, e afastará as irreverências de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 27, 'E este será o meu pacto com eles, quando eu tirar os seus pecados.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 28, 'Assim, quanto ao Evangelho, eles são inimigos, para benefício vosso; mas quanto à escolha [divina] , são amados, por causa dos patriarcas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 29, 'Pois os dons gratuitos e o chamado da parte de Deus não podem ser cancelados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 30, 'Pois, assim como vós também antigamente fostes desobedientes a Deus, agora recebestes misericórdia pela desobediência deles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 31, 'assim também agora eles foram desobedientes, a fim de que, pela misericórdia que foi a vós [concedida] , eles também recebam misericórdia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 32, 'porque Deus pôs todos debaixo da desobediência, a fim de ter misericórdia para com todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 33, 'Ó profundidade das riquezas, tanto da sabedoria como do conhecimento de Deus! Quão incompreensíveis são os seus juízos, e inimagináveis os seus caminhos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 34, 'Pois quem entendeu a mentalidade do Senhor? Ou quem foi o seu conselheiro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 35, 'Ou quem lhe deu primeiro, para ser por ele recompensado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 11, 36, 'Porque dele, por ele, e para ele, [são] todas as coisas! A ele [ seja] a glória eternamente! Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 1, 'Rogo-vos, pois, irmãos, pelas misericórdias de Deus, que apresenteis os vossos corpos como sacrifício vivo, santo e agradável a Deus, [que é] o vosso culto racional.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 2, 'E não vos conformeis com a presente era; mas transformai-vos pela renovação da vossa mentalidade, para que experimenteis qual seja a boa, agradável, e perfeita vontade de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 3, 'Pois, pela graça que me foi dada, digo a cada um dentre vós que não se estime mais do que convém se estimar; em vez disso, cada um estime a si mesmo com bom senso, conforme a medida de fé que Deus repartiu a cada um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 4, 'Porque assim como em um corpo temos muitos membros, e nem todos os membros têm a mesma função,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 5, 'assim também nós, [ainda que] muitos, somos um único corpo em Cristo; porém, individualmente, membros uns dos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 6, 'Temos, contudo, diferentes dons, segundo a graça que nos foi dada: se é o de profecia, seja segundo a medida da fé;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 7, 'se é o de serviço, seja em servir; se é o de ensino, seja em ensinar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 8, 'se é o de exortação, seja em exortar; o que reparte, [reparta] com generosidade; o que lidera, [lidere] com empenho, o que usa de misericórdia, [faça-o] com alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 9, 'O amor seja sem hipocrisia. Odiai o mal, e apegai-vos ao bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 10, 'Amai-vos cordialmente uns aos outros com amor de irmãos, preferindo honrar uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 11, 'Não sejais vagarosos em mostrardes empenho. Sede fervorosos de espírito. Servi ao Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 12, 'Alegrai-vos na esperança. Sede pacientes na aflição. Perseverai na oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 13, 'Compartilhai com os santos em suas necessidades. Buscai ser hospitaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 14, 'Abençoai os que vos perseguem; abençoai, e não amaldiçoeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 15, 'Alegrai-vos com os que se alegram, e chorai com os que choram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 16, 'Estimai-vos uns aos outros como semelhantes. Não fiqueis pensando com soberba; em vez disso, acompanhai-vos dos humildes. Não sejais sábios em vós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 17, 'A ninguém pagueis o mal com o mal; buscai fazer o que é certo diante de todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 18, 'No que for possível de vossa parte, tende paz com todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 19, 'Não vos vingueis por vós mesmos, amados. Em vez disso, dai lugar à ira [divina] ,porque está escrito: A mim pertence a vingança, eu retribuirei, diz o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 20, 'Portanto, se o teu inimigo tiver fome, dá-lhe de comer; se tiver sede, dá-lhe de beber. Pois, quando fizeres isto, estarás amontoando brasas de fogo sobre a cabeça dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 12, 21, 'Não sejas vencido pelo mal, mas vence o mal com o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 1, 'Toda pessoa esteja sujeita às autoridades superiores, porque não há autoridade que não seja da parte de Deus; e as autoridades que existem são ordenadas por Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 2, 'Por isso, quem se opõe à autoridade resiste à ordem de Deus; e os que lhe resistem trarão a si mesmos condenação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 3, 'Pois os que possuem autoridade não causam temor às boas obras, mas sim, às más. Queres tu não ter medo de autoridade? Faz o bem, e dela receberás elogio,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 4, 'porque ela é serva de Deus para o teu bem. Porém, se fizeres o mal, teme; porque ela não traz a espada em vão. Pois é serva de Deus, vingadora, para castigar a quem faz o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 5, 'Portanto, é necessário estar sujeito não somente por causa do castigo, mas também por causa da consciência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 6, 'Por isso também pagais impostos; porque são servidores de Deus, atendendo a essa função.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 7, 'Portanto, dai a cada um o que deveis; a quem imposto, imposto; a quem taxa, taxa; a quem temor, temor; a quem honra, honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 8, 'A ninguém devais coisa alguma, a não ser o amor uns aos outros, pois quem ama o outro tem cumprido a Lei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 9, 'Porque estes [mandamentos] : não adulterarás, não matarás, não roubarás, não dirás falso testemunho, não cobiçarás; e qualquer outro mandamento que há, nesta frase se resumem: “Amarás ao teu próximo como a ti mesmo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 10, 'O amor não faz mal ao próximo. Assim, o cumprimento da Lei é o amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 11, 'Além disso, conheceis o tempo, que já é hora de despertarmos do sono, porque a salvação está agora mais perto de nós do que quando começamos a crer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 12, 'A noite está se acabando, e o dia, chegando. Deixemos, pois, as obras das trevas, e vistamo-nos das armas da luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 13, 'Andemos de maneira decente, como de dia; não em orgias e bebedeiras; não em pecados sexuais ou depravações; não em brigas, nem em inveja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 13, 14, 'Em vez disso, revesti-vos do Senhor Jesus Cristo, e não fiqueis pensando em [realizar] os desejos da carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 1, 'Recebei a quem for fraco na fé, mas não para [envolvê-lo] em temas controversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 2, 'Um crê que pode comer de tudo, e outro, que é fraco, come [somente] vegetais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 3, 'O que come não despreze o que não come, e o que não come não julgue o que come, porque Deus o aceitou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 4, 'Quem és tu para julgares o servo alheio? É ao seu próprio senhor que ele fica firme ou cai. E ele ficará firme, porque Deus é poderoso para o firmar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 5, 'Um faz diferença entre um dia e outro; porém outro considera iguais todos os dias. Cada um mantenha certeza em sua própria mente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 6, 'O que faz diferença entre dias, para o Senhor a faz; e aquele que não faz diferença entre dias, para o Senhor não a faz. O que come, come para o Senhor, porque dá graças a Deus; e o que não come, deixa de comer para o Senhor, e dá graças a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 7, 'Pois nenhum de nós vive para si mesmo; e nenhum morre para si mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 8, 'Porque, se vivemos, para o Senhor vivemos; e se morremos, para o Senhor morremos. Portanto, quer vivamos, quer morramos, do Senhor somos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 9, 'Pois para isto Cristo também morreu, ressuscitou, e voltou a viver, para ser Senhor tanto dos mortos como dos vivos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 10, 'Tu, porém, por que julgas o teu irmão? Ou tu também, por que desprezas o teu irmão? Pois todos nós seremos apresentados diante do tribunal de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 11, 'Porque está escrito: [“Tão certo como] eu vivo, diz o Senhor, que todo joelho se dobrará diante de mim, e toda língua confessará a Deus”;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 12, 'de maneira que cada um de nós dará conta de si mesmo a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 13, 'Portanto, não julguemos mais uns aos outros; em vez disso, tomai a decisão de nunca pôr alguma pedra de obstáculo ou de tropeço diante do seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 14, 'Eu sei, e tenho certeza no Senhor Jesus, que nada é impuro por si mesmo; a não ser para quem o considera impuro: aquilo para ele se torna impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 15, 'Mas, se por causa do que comes o teu irmão se entristece, tu já não estás andando segundo o amor. Não destruas por tua comida aquele por quem Cristo morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 16, 'Não seja insultado o vosso bem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 17, 'porque o reino de Deus não é comida nem bebida, mas sim justiça, paz, e alegria no Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 18, 'Pois quem nessas coisas serve a Cristo é agradável a Deus e aprovado pelas pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 19, 'Sigamos, pois, as coisas que [resultam em] paz e edificação de uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 20, 'Não destruas a obra de Deus por causa da comida. É verdade que todas as coisas são limpas, porém mau é ao ser humano comer causando ofensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 21, 'Não é bom comer carne, nem beber vinho, nem [qualquer coisa] que faça o teu irmão tropeçar, ou se ofender, ou enfraquecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 22, 'A convicção que tu tens, tenha-a para ti mesmo diante de Deus. Feliz é quem não se culpa naquilo que aprova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 14, 23, 'Mas aquele que tem dúvida, se comer, é culpado, porque não foi pela fé; e tudo que não é pela fé é pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 1, 'Mas nós, que somos fortes, devemos suportar as fraquezas dos fracos, e não agradar a nós mesmos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 2, 'Portanto, cada um de nós agrade ao próximo no que é bom para a edificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 3, 'Pois também Cristo não agradou a si mesmo; mas, como está escrito: “Os insultos dos que te insultavam caíram sobre mim”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 4, 'Pois todas as coisas que foram escritas com antecedência foram escritas para o nosso ensino; para que, pela paciência e consolação das Escrituras, tenhamos esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 5, 'O Deus da paciência e da consolação vos dê a mesma mentalidade uns para com os outros, segundo Cristo Jesus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 6, 'a fim de que, em comum acordo, como uma só boca, glorifiqueis ao Deus e Pai de nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 7, 'Portanto, recebei uns aos outros, assim como também Cristo nos recebeu para a glória de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 8, 'E digo que Jesus Cristo se tornou servidor da circuncisão por causa da verdade de Deus, para confirmar as promessas [feitas] aos patriarcas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 9, 'e para que os gentios glorifiquem a Deus por causa de [sua] misericórdia, como está escrito: “Por isso entre os gentios te confessarei, e ao teu nome cantarei.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 10, 'E outra vez diz: “Alegrai-vos, gentios, com o povo dele.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 11, 'E outra vez: “Louvai ao Senhor todas as nações, e celebrai-o todos os povos.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 12, 'E outra vez Isaías diz: “Haverá a raiz de Jessé, e aquele que se levantará para governar as nações; nele os gentios esperarão.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 13, 'O Deus da esperança vos encha de toda alegria e paz na fé, para que abundeis em esperança no poder do Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 14, 'Porém, meus irmãos, convencido estou acerca de vós de que também estais cheios de bondade, plenos de todo conhecimento, e capazes de também aconselhardes uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 15, 'Mas, irmãos, em parte vos escrevi com mais ousadia, como que para vos relembrar, por causa da graça que me foi dada por Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 16, 'a fim de que eu seja um servidor de Jesus Cristo entre os gentios, ministrando o evangelho de Deus, para que a oferta dos gentios seja agradável, santificada pelo Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 17, 'Assim eu me orgulho em Jesus Cristo das coisas relacionadas a Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 18, 'Pois eu não ousaria falar coisa alguma, a não ser o que Cristo fez por meio de mim, para tornar os gentios obedientes, por meio da palavra e da obra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 19, 'com poder de sinais e milagres, no poder do Espíritode Deus; de maneira que desde Jerusalém e redondezas até Ilírico, cumpri a pregação do Evangelho de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 20, 'E assim quis muito anunciar o Evangelho onde Cristo não houvesse sido pregado, para que eu não construísse sobre fundamento alheio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 21, 'ao contrário, como está escrito: “Aqueles a quem dele não foi anunciado [o] verão; e os que não ouviram entenderão.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 22, 'Por isso também muitas vezes tenho sido impedido de ir até vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 23, 'Mas agora, como nessas regiões não há mais lugar em que eu precise trabalhar, e já por muitos anos tive grande desejo de ir até vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 24, 'quando eu for para a Espanha pois espero vos ver no caminho, e receber ajuda de vossa parte para a viagem, depois de primeiramente ficar um tempo satisfazendo o desejo de estar convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 25, 'Mas por ora, vou a Jerusalém, a fim de auxiliar os santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 26, 'Pois, aos da Macedônia e Acaia pareceu bem fazer uma contribuição para os pobres dentre os santos que estão em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 27, '[Isso] lhes pareceu bem, como quem está em dívida para com eles; porque, se os gentios foram participantes dos seus [bens] espirituais, devem também ajudá-los com os materiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 28, 'Assim que eu concluir isso, e garantir [a entrega] desse fruto a eles, partirei para a Espanha passando para vos visitar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 29, 'E sei que, quando chegar até vós, virei com a plenitude da bênção do Evangelho de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 30, 'Rogo-vos, porém, irmãos, pelo nosso Senhor Jesus Cristo, e pelo amor do Espírito, que luteis comigo em orações a Deus por mim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 31, 'para que eu esteja livre dos rebeldes na Judeia, e que este meu serviço em Jerusalém seja bem aceito pelos santos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 32, 'a fim de que eu possa chegar até vós com alegria, pela vontade de Deus, e que eu possa descansar convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 15, 33, 'E o Deus da paz esteja com todos vós. Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 1, 'Eu vos recomendo a nossa irmã Febe, que é servidora da Igreja que está em Cencreia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 2, 'para que a recebais no Senhor, como convém aos santos; e para que a ajudeis em qualquer coisa que necessitar de vós; pois ela tem ajudado a muitos, inclusive a mim mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 3, 'Saudai a Priscila e a Áquila, meus cooperadores em Cristo Jesus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 4, 'que arriscaram seus pescoços por minha vida; a eles não somente eu agradeço, como também todas as igrejas dos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 5, '[Saudai] também a igreja [que se reúne] na casa deles. Saudai Epêneto, meu amado, que é o primeiro fruto da Acaia para Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 6, 'Saudai Maria, que trabalhou muito por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 7, 'Saudai Andrônico e Júnia, meus parentes, e meus companheiros na prisão, que são notáveis entre os apóstolos, e também estavam antes de mim em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 8, 'Saudai Amplias, meu amado no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 9, 'Saudai Urbano, nosso cooperador em Cristo, e Estáquis, meu amado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 10, 'Saudai Apeles, aprovado em Cristo. Saudai os que são da [casa] de Aristóbulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 11, 'Saudai Herodião, meu parente. Saudai os que são da [casa] de Narciso, que estão no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 12, 'Saudai Trifena e Trifosa, que trabalham no Senhor. Saudai a amada Pérside, que trabalhou muito no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 13, 'Saudai Rufo, o escolhido no Senhor, e a mãe dele, e minha também.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 14, 'Saudai Asíncrito, Flegonte, Hermas, Pátrobas, Hermes e os irmãos que estão com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 15, 'Saudai Filólogo, Júlia, Nereu e sua irmã, Olimpas, e todos os santos que estão com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 16, 'Saudai-vos uns aos outros com beijo santo. As igrejas de Cristo vos saúdam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 17, 'E rogo-vos, irmãos, que sejais cuidadosos com os que causam divisões e obstáculos contrários à doutrina que aprendestes; e afastai-vos deles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 18, 'pois tais pessoas não servem ao nosso Senhor Jesus Cristo, mas sim, ao próprio ventre; e com palavras suaves e elogios enganam os corações dos ingênuos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 19, 'Pois a vossa obediência chegou [ao conhecimento] de todos. Por isso eu me alegro por vossa causa; quero, porém, que sejais sábios no bem, e inocentes quanto ao mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 20, 'E o Deus de paz esmagará Satanás em pedaços debaixo dos vossos pés. A graça de nosso Senhor Jesus Cristo seja convosco. Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 21, 'Saúdam-vos o meu cooperador Timóteo, e os meus parentes Lúcio, Jáson, e Sosípatro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 22, 'Eu, Tércio, que escrevi [esta] carta, vos saúdo no Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 23, 'Gaio, hospedeiro meu e toda a igreja, vos saúda. Erasto, tesoureiro da cidade, vos saúda, e também o irmão Quarto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 24, 'A graça de nosso Senhor Jesus Cristo seja com todos vós, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 25, 'Ora, para aquele que tem o poder de vos manter firmes segundo o meu Evangelho e a pregação de Jesus Cristo, conforme a revelação do mistério, que foi encoberto [desde] o princípio dos tempos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 26, 'Mas agora se manifestou, e se tornou conhecido pelas Escrituras dos profetas, segundo o mandado do Deus eterno, para a obediência da fé entre todas as nações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 45, 'Romanos', 'Rm', 16, 27, 'Ao único Deus sábio seja a glória, por meio de Jesus Cristo, para [todo o] sempre! Amém! [Escrita de Corinto aos Romanos, e enviada por Febe, servidora da igreja de Cencreia.]'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 1, 'Paulo, chamado apóstolo de Jesus Cristo pela vontade de Deus, e o irmão Sóstenes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 2, 'À igreja de Deus que está em Corinto, aos santificados em Cristo Jesus, chamados santos, com todos os que em todo lugar invocam o nome de nosso Senhor Jesus Cristo, [Senhor] deles, e nosso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 3, 'Graça [seja] convosco, e a paz de Deus nosso Pai, e do Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 4, 'Sempre agradeço ao meu Deus por causa de vós, pela graça de Deus, que é dada a vós em Cristo Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 5, 'Que em todas as coisas estais enriquecidos nele, em toda palavra, e em todo conhecimento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 6, 'Assim como o testemunho de Jesus Cristo foi confirmado entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 7, 'De maneira que nenhum dom vos falta, enquanto esperais a manifestação do nosso Senhor Jesus Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 8, 'o qual também vos firmará até o fim, irrepreensíveis no dia de nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 9, 'Fiel é Deus, por quem fostes chamados para a comunhão do seu Filho Jesus Cristo, nosso Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 10, 'Mas eu vos rogo, irmãos, pelo nome do nosso Senhor Jesus Cristo, que todos faleis uma mesma coisa, e não haja divisões entre vós; antes estejais juntos com o mesmo entendimento, e com a mesma opinião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 11, 'Porque, meus irmãos, foi-me informado acerca de vós, pelos [da casa] de Cloé, de que há brigas entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 12, 'E digo isto, que cada um de vós diz: “Eu sou de Paulo” e “Eu [sou] de Apolo” e “Eu [sou] de Cefas” e “Eu [sou] de Cristo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 13, 'Cristo está dividido? Paulo foi crucificado por vós? Ou fostes vós batizados no nome de Paulo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 14, 'Agradeço a Deus que batizei nenhum de vós, a não ser Crispo e Gaio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 15, 'para que ninguém diga que eu tenha batizado em meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 16, 'Também batizei aos da casa de Estefanas; além desses, não sei se batizei algum outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 17, 'Porque Cristo não me enviou para batizar, mas sim, para evangelizar; não com sabedoria de palavras, para que a cruz de Cristo não se torne inútil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 18, 'Porque a palavra da cruz é loucura para os que perecem; mas para os que se salvam é poder de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 19, 'Porque está escrito: Destruirei a sabedoria dos sábios, e aniquilarei a inteligência dos inteligentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 20, 'Onde está o sábio? Onde está o escriba? Onde está o questionador desta era? Por acaso Deus não tornou a sabedoria deste mundo em loucura?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 21, 'Pois já que, na sabedoria de Deus, o mundo não conheceu a Deus pela sabedoria, Deus se agradou de salvar os que creem por meio da loucura da pregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 22, 'Porque os judeus pedem um sinal miraculoso, e os gregos buscam sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 23, 'Mas nós pregamos a Cristo crucificado, [que é] motivo de ofensa para os Judeus, e loucura para os gregos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 24, 'Porém aos que são chamados, tanto judeus como gregos, Cristo [é] poder de Deus e sabedoria de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 25, 'Porque a loucura de Deus é mais sábia que os seres humanos; e a fraqueza de Deus é mais forte que os seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 26, 'Vede, pois, o vosso chamado, irmãos; pois dentre vós não [há] muitos sábios em sabedoria humana, nem muitos poderosos, nem muitos da elite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 27, 'Mas Deus escolheu as coisas loucas deste mundo para envergonhar as sábias; e Deus escolheu as fracas deste mundo para envergonhar as fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 28, 'E Deus escolheu as coisas desprezíveis deste mundo, e as sem valor, e as que não são, para reduzir a nada as que são;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 29, 'para que ninguém orgulhe de si mesmo diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 30, 'Mas vós sois dele em Cristo Jesus, o qual, por parte de Deus, tornou-se para nós sabedoria, justiça, santificação, e resgate;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 1, 31, 'para que, assim como está escrito: “Aquele que se orgulha, orgulhe-se no Senhor”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 1, 'E eu, irmãos, quando vim até vós, não vim vos anunciar o testemunho de Deus com excelência de palavras, ou sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 2, 'Porque não quis saber coisa alguma entre vós, a não ser Jesus Cristo, e ele crucificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 3, 'E eu estive convosco em fraqueza, em temor, e em grande tremor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 4, 'E a minha palavra e a minha pregação não foram em palavras persuasivas de sabedoria humana, mas sim, em demonstração do Espírito e de poder;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 5, 'para que a vossa fé não fosse em sabedoria humana, mas sim, no poder de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 6, 'Contudo, falamos sabedoria entre os maduros, porém uma sabedoria não deste mundo, nem dos líderes deste mundo, que perecem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 7, 'Mas falamos a sabedoria de Deus, oculta em mistério, a qual Deus ordenou antes dos tempos para a nossa glória;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 8, 'a [sabedoria] que nenhum dos líderes deste mundo conheceu. Porque, se a tivessem conhecido, nunca teriam crucificado ao Senhor da glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 9, 'Porém, assim como está escrito: “As coisas que o olho não viu, e não subiram que ao coração humano, [são] as que Deus preparou para os que o amam”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 10, 'Mas Deus as revelou para nós pelo seu Espírito. Porque o Espírito investiga todas as coisas, até as profundezas de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 11, 'Pois quem dentre os seres humanos sabe as coisas do ser humano, senão o espírito do ser humano que nele está? Assim também ninguém sabe as coisas de Deus, senão o Espírito de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 12, 'Nós, porém, não recebemos o espírito do mundo, mas sim, o Espírito que provém de Deus; para que saibamos as coisas que por Deus nos são dadas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 13, 'as quais também falamos, não com palavras que a sabedoria ensina, mas com as que o Espírito Santo ensina, interpretando [coisas] espirituais por [meios] espirituais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 14, 'Mas o ser humano natural não compreende as coisas que são do Espírito de Deus, porque lhe são loucura; e não as pode entender, porque se compreendem espiritualmente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 15, 'Porém quem é espiritual compreende todas as coisas, mas não é compreendido por ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 2, 16, 'Pois quem conheceu a mente do Senhor, para que o possa instruir? Mas nós temos a mente de Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 1, 'E eu, irmãos, não pude vos falar como a espirituais, mas como a carnais, como a meninos em Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 2, 'Com leite eu vos criei, e não com alimento sólido, porque não podíeis; nem mesmo agora ainda podeis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 3, 'porque ainda sois carnais. Pois, havendo entre vós inveja, brigas, e divisões, por acaso não sois carnais, e andais fazendo conforme o costume humano?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 4, 'Porque dizendo um: “Eu sou de Paulo”, e outro: “Eu [sou] de Apolo”, por acaso não sois carnais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 5, 'Ora, quem é Paulo, e quem é Apolo, senão servidores, pelos quais crestes, conforme o Senhor deu a cada um?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 6, 'Eu plantei; Apolo regou; mas foi Deus quem deu o crescimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 7, 'De maneira que nem o que planta é algo, nem o que rega; mas sim Deus, que dá o crescimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 8, 'E o que planta e o que rega são um; mas cada um receberá a sua recompensa segundo o seu trabalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 9, 'Porque somos cooperadores de Deus; vós sois a plantação de Deus, o edifício de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 10, 'Segundo a graça de Deus que me foi dada, eu, como sábio construtor, pus o fundamento; e outro edifica sobre ele; mas cada um veja como edifica sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 11, 'Pois ninguém pode pôr fundamento diferente do que já está posto, o qual é Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 12, 'E se alguém sobre este fundamento edificar ouro, prata, pedras preciosas, madeira, feno, palha,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 13, 'a obra de cada um se manifestará; porque o dia a esclarecerá; pois pelo fogo se descobre; e qual é a obra de cada um, o fogo fará a prova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 14, 'Se a obra de alguém que construiu sobre ele permanecer, receberá recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 15, 'Se a obra de alguém se queimar, ele sofrerá perda; porém o tal se salvará, todavia, como que [passado] pelo fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 16, 'Não sabeis vós, que sois o templo de Deus? E que o Espírito de Deus habita em vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 17, 'Se alguém destruir o templo de Deus, Deus ao tal destruirá; porque o templo de Deus é santo, o qual sois vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 18, 'Ninguém se engane; se alguém entre vós nestes tempos pensa ser sábio, que se faça de louco, para que seja sábio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 19, 'Pois a sabedoria deste mundo é loucura para Deus; porque está escrito: Ele toma aos sábios pela sua própria astúcia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 20, 'E outra vez: O Senhor conhece os pensamentos dos sábios, que são vãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 21, 'Portanto ninguém se orgulhe em seres humanos; porque tudo é vosso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 22, 'seja Paulo, seja Apolo, seja Cefas, seja o mundo, seja a vida, seja a morte, seja o presente, seja o futuro; tudo é vosso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 3, 23, 'Mas vós sois de Cristo; e Cristo, de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 1, 'Que as pessoas nos considerem como servidores de Cristo, e guardiões dos mistérios de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 2, 'Além disso, exige-se dos guardiões que cada um seja fiel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 3, 'Quanto a mim, pouco me importa ser julgado por vós, ou por qualquer juízo humano; nem eu julgo a mim mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 4, 'Porque em nada me sinto culpável; mas nem por isso estou justificado; porém quem me julga é o Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 5, 'Então nada julgueis antes do tempo, até que o Senhor venha, o qual também trará à luz as coisas ocultas nas trevas, e manifestará as intenções dos corações; e então cada um receberá de Deus a aprovação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 6, 'E isto, irmãos, fiz a comparação relativa a mim e a Apolo por causa de vós; para que em nós aprendais a não fazer suposições além do que está escrito; para que não fiqueis arrogantes por preferir um contra o outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 7, 'Pois quem te faz diferentemente superior? E o que tens tu, que não tenhas recebido? E se o recebeste, por que te orgulhas, como se não o tivesse recebido?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 8, 'Vós já estais satisfeitos, já estais ricos, e reinastes sem nós; e bom seria se vós reinásseis, para que também nós reinássemos convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 9, 'Pois acho que Deus colocou a nós, os apóstolos, por último, como sentenciados à morte; pois somos como espetáculo ao mundo, tanto aos anjos como aos seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 10, 'Nós [somos] loucos por causa de Cristo, mas vós sábios em Cristo; nós fracos, mas vós fortes; vós ilustres, mas nós desonrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 11, 'Até esta presente hora sofremos fome e sede, e estamos nus, e somos golpeados, e não temos morada certa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 12, 'E ficamos exaustos, trabalhando com as nossas próprias mãos; somos insultados, e bendizemos; somos perseguidos, e nós suportamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 13, 'Somos blasfemados, e respondemos humildemente; somos feitos como a escória do mundo, e como o lixo de todos, até agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 14, 'Não escrevo estas coisas para vos envergonhar; mas sim, para [vos] advertir como a meus amados filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 15, 'Porque ainda que tivésseis dez mil tutores em Cristo, contudo não [tendes] muitos pais. Porque eu vos gerei em Cristo Jesus por meio do Evangelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 16, 'Portanto eu vos chamo para que sejais meus imitadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 17, 'Por isso eu vos enviei Timóteo, que é meu filho amado e fiel no Senhor; ele vos lembrará dos meus caminhos em Cristo, como por todos os lugares eu ensino em cada igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 18, 'Mas alguns andam arrogantes, como se eu não fosse até vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 19, 'Porém logo irei vos visitar, se o Senhor quiser; e [então] conhecerei, não as palavras dos que andam arrogantes, mas sim o poder [deles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 20, 'Porque o Reino de Deus não [consiste] de palavras, mas sim de poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 4, 21, 'Que quereis? Que eu venha até vós com a vara [da disciplina] , ou com amor e espírito de mansidão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 1, 'Totalmente se ouve [que há] entre vós pecados sexuais, e tais pecados sexuais que nem mesmo entre os gentios se nomeia, como alguém que tomou como mulher a esposa de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 2, 'E vós estais orgulhosos! Ao invés disso, vós não deveríeis se entristecer, para que fosse tirado do meio de vós o que cometeu esta atitude?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 3, 'Porque eu, [agindo] como ausente de corpo, porém presente de espírito, já julguei como se estivesse presente, aquele que fez isto,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 4, 'No nome do nosso Senhor Jesus Cristo, quando vós vos reunirdes, e o meu espírito junto de vós, com o poder de nosso Senhor Jesus Cristo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 5, 'De ao tal entregar a Satanás, para destruição da carne, para que o espírito seja salvo, no dia do Senhor Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 6, 'Vosso orgulho não é bom. Não sabeis que um pouco de fermento faz levedar toda a massa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 7, 'Limpai pois o velho fermento, para que sejais nova massa, assim como vós sois [de fato] sem fermento. Porque Cristo, nosso [cordeiro da] páscoa, foi sacrificado por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 8, 'Portanto façamos festa, não no velho fermento, nem no fermento do mal e da perversão, mas em pães não levedados de sinceridade e de verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 9, 'Eu já vos escrevi por carta, que não vos mistureis com pecadores sexuais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 10, 'Porém não totalmente com os pecadores deste mundo, ou com os gananciosos, ou ladrões, ou [com os] idólatras; porque então vos seria necessário sair do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 11, 'Mas agora vos escrevo, que não vos mistureis se alguém, chamando a si de irmão, for pecador sexual, ou ganancioso, ou idólatra, ou maldizente, ou beberrão, ou ladrão. Com o tal nem mesmo comais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 12, 'Por que eu tenho que julgar também aos que estão de fora? Não julgais vós aos que estão de dentro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 5, 13, 'Mas Deus julga aos que estão de fora. Tirai pois dentre vós a este maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 1, 'Algum de vós, tendo um assunto contra outro, ousa ir a juízo perante os injustos, e não perante os santos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 2, 'Não sabeis que os santos julgarão ao mundo? E se o mundo é julgado por vós, por acaso sois vós indignos de julgar as coisas mínimas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 3, 'Não sabeis que julgaremos aos anjos? Quanto mais as coisas desta vida!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 4, 'Pois se tiverdes assuntos em juízo, relativos a coisas desta vida, vós pondes como juízes aos que são menos estimados pela igreja?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 5, 'Eu digo [isto] para vos envergonhar. Não há entre vós algum sábio, nem pelo menos um, que não possa julgar entre seus irmãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 6, 'Mas irmão vai a juízo contra outro irmão, e isto perante incrédulos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 7, 'Porém já é uma falta entre vós, por entre vós haverdes disputas. Por que não aceitais serdes injustiçados? Por que não aceitais o prejuízo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 8, 'Mas vós [mesmos] injustiçais e prejudicais, e isto aos irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 9, 'Ou não sabeis que os injustos não herdarão o Reino de Deus? Não erreis: nem os pecadores sexuais, nem os idólatras, nem os adúlteros, nem os sexualmente efeminados, nem os homens que fazem sexo com homens,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 10, 'Nem os ladrões, nem os gananciosos, nem os beberrões, nem os maldizentes, nem os extorsores herdarão o Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 11, 'E isto alguns de vós éreis. Mas [já] estais lavados, e santificados, e justificados no nome do Senhor Jesus, e pelo Espírito de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 12, 'Todas as coisas me são lícitas, mas nem todas as coisas convêm; todas as coisas me são lícitas, porém eu não deixarei me sujeitar por coisa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 13, 'A comida é para o estômago, e o estômago é para a comida; mas Deus os aniquilará, tanto a um, como ao outro. Porém o corpo não é para o pecado sexual, mas para o Senhor, e o Senhor [é] para o corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 14, 'E Deus ressuscitou ao Senhor, e também por seu poder nos ressuscitará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 15, 'Não sabeis vós que vossos corpos são membros de Cristo? Tomarei pois os membros de Cristo, e os farei membros de uma prostituta? De maneira nenhuma!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 16, 'Ou não sabeis que o que se junta [sexualmente] com uma prostituta se torna um [só] corpo [com ela] ? Porque [a Escritura] diz: Os dois serão uma [só] carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 17, 'Mas o que se junta com o Senhor, [com ele] se torna um [só] espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 18, 'Fugi do pecado sexual. Todo pecado que o ser humano comete é fora do corpo; mas o que pratica pecado sexual, peca contra seu próprio corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 19, 'Ou não sabeis que vosso corpo é templo do Espírito Santo, o qual está em vós, o qual tendes de Deus, e [que] não sois de vós mesmos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 6, 20, 'Porque vós fostes comprados por alto preço; então glorificai a Deus em vosso corpo, e em vosso espírito, que são de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 1, 'E sobre as coisas que me escrevestes, bom é para o homem não tocar mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 2, 'Mas por causa dos pecados sexuais, tenha cada um sua própria mulher, e cada uma tenha seu próprio marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 3, 'Que o marido satisfaça sua mulher como devido, e semelhantemente a mulher ao marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 4, 'A mulher não tem poder sobre seu próprio corpo, mas sim o marido; e também da mesma maneira o marido não tem poder sobre seu próprio corpo, mas sim a mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 5, 'Não vos priveis um ao outro, a não ser por consentimento [de ambos] por algum tempo, para que vos ocupeis com jejum, e para a oração; e voltai-vos outra vez a se juntarem, para que Satanás não vos tente, por causa de vossa falta de domínio próprio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 6, 'Mas isto vos digo como permissão, não como mandamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 7, 'Porque eu queria que todos fossem como eu mesmo; mas cada um tem seu próprio dom de Deus, um de um jeito assim, e outro de um jeito diferente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 8, 'Mas digo aos solteiros, e às viúvas que lhes é bom se permanecessem como eu estou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 9, 'Mas se não podem se conter, casem-se; porque é melhor se casar do que se inflamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 10, 'Porém aos casados eu mando, não eu, mas o Senhor, que a mulher não se separe do marido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 11, 'E se se separar, fique sem casar, ou se reconcilie com o marido; e que o marido não deixe a mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 46, '1 Coríntios', '1Co', 7, 12, 'Mas aos outros digo eu, não o Senhor: se algum irmão tem mulher descrente, e ela consente em habitar com ele, não a deixe.')
